#pragma once

#include <cstdint>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

#include <libbsa/archive.hpp>
#include <libbsa/export.hpp>
#include <libbsa/result.hpp>

namespace libbsa
{

  /// Stable compatibility warning identifiers returned by validation reports.
  ///
  /// Codes are intended for programmatic branching. Human-readable messages may
  /// change as diagnostics improve, but these identifiers remain the public
  /// compatibility contract for warning categories.
  enum class compatibility_warning_code
  {
    compressed_sound_payload,
    bsa_embedded_name_compatibility_risk,
    target_family_mismatch,
  };

  /// Severity for compatible-but-noteworthy validation warnings.
  ///
  /// `advisory` warnings describe information a consumer may want to display.
  /// `risky` warnings describe archives that can be valid while still carrying a
  /// known interoperability risk.
  enum class compatibility_warning_severity
  {
    advisory,
    risky,
  };

  /// Fatal archive validation diagnostic.
  ///
  /// `code` is the stable public error category. `message` is diagnostic text for
  /// humans and should not be treated as a stable machine-readable value.
  struct validation_diagnostic
  {
    /// Stable public error category for the validation failure.
    error_code code;

    /// Human-readable diagnostic text for logs or UI display.
    std::string message;
  };

  /// Compatibility warning emitted for a valid but noteworthy archive condition.
  ///
  /// Warnings keep stable code and severity values separate from human-readable
  /// text. `archive_path` is present only when the warning applies to one entry.
  struct compatibility_warning
  {
    /// Stable public warning category.
    compatibility_warning_code code;

    /// Warning severity for display, sorting, or caller escalation.
    compatibility_warning_severity severity;

    /// Human-readable warning text for logs or UI display.
    std::string message;

    /// Optional normalized archive path when the warning applies to a specific entry.
    std::optional<std::string> archive_path;
  };

  /// Caller-selected validation policy.
  ///
  /// Options are intentionally small: callers may assert the expected archive
  /// family, expected variant, and whether every entry should be extracted during
  /// validation.
  struct validation_options
  {
    /// Expected top-level archive family, when the caller knows it in advance.
    std::optional<archive_type> expected_type;

    /// Expected archive variant, when the caller knows it in advance.
    std::optional<archive_variant> expected_variant;

    /// True to validate entry extraction in addition to archive structure.
    bool validate_entry_extractability{false};

    /// Maximum declared stored or decoded bytes extracted per entry during validation.
    ///
    /// This limit applies only when `validate_entry_extractability` is true. Entries
    /// above the limit become structured validation diagnostics instead of causing
    /// validation to allocate archive-controlled payload sizes.
    std::uint64_t max_extractability_entry_bytes{64U * 1024U * 1024U};
  };

  /// Structured validation result for an archive host path.
  ///
  /// Reports expose only overall validity, optional archive metadata, fatal
  /// diagnostics, and compatibility warnings. They do not expose parser offsets,
  /// record indexes, chunk indexes, entry listings, or extraction bytes.
  ///
  /// Thread-safety: reports are independent values after return; see
  /// `docs/thread-safety.md` for validation result inspection rules.
  struct validation_report
  {
    /// True when no fatal validation errors were found.
    bool valid{false};

    /// Archive metadata when it could be parsed safely.
    std::optional<archive_metadata> metadata;

    /// Fatal validation diagnostics that make the archive invalid.
    std::vector<validation_diagnostic> errors;

    /// Compatible-but-noteworthy archive conditions found during validation.
    std::vector<compatibility_warning> warnings;

    /// Returns true when the report represents a valid archive.
    [[nodiscard]] LIBBSA_API bool is_valid() const noexcept;
  };

  /// Validates an archive host path and returns structured diagnostics.
  ///
  /// Result-level failures are reserved for call/setup failures such as invalid
  /// or unreadable host paths. Inspectable archive problems are reported inside
  /// `validation_report::errors` so callers can display all available diagnostics.
  ///
  /// Thread-safety: validation uses no global mutable state, so independent calls
  /// may run concurrently subject to the host filesystem.
  [[nodiscard]] LIBBSA_API result<validation_report> validate_archive(std::string_view host_path,
                                                                      validation_options options = {});

} // namespace libbsa

  public:
    virtual ~bulk_extract_sink_factory() = default;

    /// Creates the sink that will receive the payload for the unique request `path`.
    ///
    /// Returning an error records a per-entry failure and does not abort
    /// independent sibling entries.
    virtual result<std::unique_ptr<payload_sink>> create(std::string_view path, const entry_metadata &entry) = 0;
  };

  /// Per-request result record returned by `archive_reader::extract_entries`.
  ///
  /// Thread-safety: result records are independent values after the caller-owned
  /// result vector is no longer being mutated.
  struct bulk_extract_entry_result
  {
    /// Requested archive path in the same order supplied by the caller.
    std::string path;

    /// Entry metadata when lookup succeeded before extraction.
    std::optional<entry_metadata> entry;

    /// Per-entry failure, if lookup, sink creation, or extraction failed.
    std::optional<error> failure;

    /// Returns true when this record completed without a per-entry failure.
    [[nodiscard]] bool succeeded() const noexcept { return !failure.has_value(); }
  };

  /// Public archive reader for supported Bethesda archive files.
  ///
  /// Use `open()` for fallible construction. A successfully opened reader exposes
  /// archive metadata, deterministic entry listings, canonical path lookup, and
  /// synchronous extraction for the archive variants implemented by libbsa.
  ///
  /// Thread-safety: independently opened readers may be used concurrently; one
  /// reader may run concurrent const extraction calls only with distinct sinks as
  /// described in `docs/thread-safety.md`.
  class archive_reader
  {
  public:
    /// Attempts to open an archive from a host path string.
    ///
    /// Empty host paths return `error_code::invalid_argument`, missing or
    /// unreadable files return `error_code::io_error`, unsupported archive bytes
    /// return `error_code::unsupported`, and malformed supported archives return
    /// `error_code::format_error`.
    static LIBBSA_API result<archive_reader> open(std::string_view host_path);

    /// Returns archive-level metadata for a successfully opened archive.
    [[nodiscard]] LIBBSA_API result<archive_metadata> metadata() const;

    /// Returns deterministic entry metadata sorted by canonical archive path.
    [[nodiscard]] LIBBSA_API result<std::vector<entry_metadata>> entries() const;

    /// Finds metadata for a normalized archive path if it exists.
    ///
    /// Invalid archive path syntax is reported as `error_code::invalid_argument`;
    /// valid missing paths return an empty optional so lookup can distinguish
    /// absence from malformed caller input.
    [[nodiscard]] LIBBSA_API result<std::optional<entry_metadata>> find(std::string_view path) const;

    /// Returns whether a valid archive path exists in the opened archive.
    [[nodiscard]] LIBBSA_API result<bool> contains(std::string_view path) const;

    /// Extracts an entry by archive path into a synchronous caller-owned sink.
    [[nodiscard]] LIBBSA_API result<void> extract(std::string_view path, payload_sink &sink) const;

    /// Extracts an entry into a bounded in-memory byte vector convenience result.
    [[nodiscard]] LIBBSA_API result<std::vector<std::byte>> extract_bytes(std::string_view path) const;

    /// Extracts multiple request records into caller-created unique-path sinks.
    ///
    /// Setup failures such as an unopened reader or `worker_count == 0` fail the
    /// outer result. Lookup, sink-creation, and extraction failures are recorded
    /// on the corresponding request-order result record so independent sibling
    /// entries can still complete. Duplicate exact request paths are coalesced:
    /// the first occurrence owns lookup, sink creation, and extraction, while
    /// later duplicate result records preserve their request path and mirror the
    /// first occurrence's entry and failure outcome.
    [[nodiscard]] LIBBSA_API result<std::vector<bulk_extract_entry_result>> extract_entries(
        std::span<const bulk_extract_request> requests,
        bulk_extract_sink_factory &sink_factory,
        bulk_extract_options options = {}) const;

  private:
    struct state;

    explicit archive_reader(archive_metadata metadata);

    std::shared_ptr<const state> state_;
  };

} // namespace libbsa

  /// archives use one raw payload per archive entry.
  ///
  /// Thread-safety: separately constructed or moved-to writer objects may be used
  /// concurrently, but mutation is not concurrent with other mutation or
  /// `write_to` on the same writer object. See `docs/thread-safety.md`.
  class tes3_bsa_writer
  {
  public:
    /// Creates a raw/uncompressed TES3 writer using default writer options.
    LIBBSA_API tes3_bsa_writer();

    /// Creates a raw/uncompressed TES3 writer using explicit finalization options.
    LIBBSA_API explicit tes3_bsa_writer(tes3_bsa_writer_options options);

    /// Destroys the writer and releases any staged archive state it owns.
    LIBBSA_API ~tes3_bsa_writer();

    /// Copying is disabled because writer copies would alias mutable staged entries.
    tes3_bsa_writer(const tes3_bsa_writer &) = delete;

    /// Copy assignment is disabled because writer copies would alias mutable staged entries.
    tes3_bsa_writer &operator=(const tes3_bsa_writer &) = delete;

    /// Transfers staged entries and options from `other`; `other` is valid only for destruction or reassignment.
    LIBBSA_API tes3_bsa_writer(tes3_bsa_writer &&other) noexcept;

    /// Replaces this writer by taking staged entries and options from `other`.
    ///
    /// After the move, `other` is valid only for destruction or reassignment.
    LIBBSA_API tes3_bsa_writer &operator=(tes3_bsa_writer &&other) noexcept;

    /// Returns the immutable TES3 writer options selected at construction time.
    [[nodiscard]] LIBBSA_API const tes3_bsa_writer_options &options() const noexcept;

    /// Adds a host-file payload with an explicit TES3 archive-internal path.
    ///
    /// The archive path and non-empty host path are validated at add time; source
    /// file existence is checked when `write_to` finalizes the archive.
    LIBBSA_API result<void> add_file(std::string_view archive_path, std::string_view host_path);

    /// Adds bytes copied from caller memory with an explicit TES3 archive-internal path.
    ///
    /// The writer owns an independent copy after this call, so callers may release
    /// or mutate the original memory before `write_to` is called.
    LIBBSA_API result<void> add_bytes(std::string_view archive_path, std::span<const std::byte> bytes);

    /// Finalizes the writer state into a raw/uncompressed TES3 archive at `host_path`.
    ///
    /// Existing destinations fail unless `tes3_bsa_writer_options::overwrite_existing`
    /// was enabled. Publication uses a writer-owned temporary directory beside `host_path`,
    /// overwrites only supported regular-file destinations, rejects detectable reparse points,
    /// and returns validation or I/O failures as structured errors.
    LIBBSA_API result<void> write_to(std::string_view host_path) const;

    /// Finalizes the TES3 writer using explicit write-call execution controls.
    ///
    /// `execution.worker_count` must be positive. TES3 output has no compression
    /// work, so values greater than one are accepted for the uniform public shape
    /// while preserving the existing serial output path and publication policy.
    LIBBSA_API result<void> write_to(std::string_view host_path, write_execution_options execution) const;

  private:
    struct state;

    std::unique_ptr<state> state_;
  };

  /// Public writer for creating new BA2 GNRL archives.
  ///
  /// Entries are added with explicit archive-internal paths and finalized only to
  /// a host-path archive. Memory-buffer entries are copied into writer-owned state,
  /// and codec implementation details stay private behind the selected target profile.
  ///
  /// Thread-safety: separately constructed or moved-to writer objects may be used
  /// concurrently, but mutation is not concurrent with other mutation or
  /// `write_to` on the same writer object. See `docs/thread-safety.md`.
  class ba2_gnrl_writer
  {
  public:
    /// Creates a writer for `target` using default BA2 GNRL writer options.
    LIBBSA_API explicit ba2_gnrl_writer(ba2_gnrl_target target);

    /// Creates a writer for `target` using the supplied compatibility options.
    LIBBSA_API explicit ba2_gnrl_writer(ba2_gnrl_target target, ba2_gnrl_writer_options options);

    /// Destroys the writer and releases any staged archive state it owns.
    LIBBSA_API ~ba2_gnrl_writer();

    /// Copying is disabled because writer copies would alias mutable staged entries.
    ba2_gnrl_writer(const ba2_gnrl_writer &) = delete;

    /// Copy assignment is disabled because writer copies would alias mutable staged entries.
    ba2_gnrl_writer &operator=(const ba2_gnrl_writer &) = delete;

    /// Transfers staged entries and options from `other`; `other` is valid only for destruction or reassignment.
    LIBBSA_API ba2_gnrl_writer(ba2_gnrl_writer &&other) noexcept;

    /// Replaces this writer by taking staged entries and options from `other`.
    ///
    /// After the move, `other` is valid only for destruction or reassignment.
    LIBBSA_API ba2_gnrl_writer &operator=(ba2_gnrl_writer &&other) noexcept;

    /// Returns the BA2 GNRL target profile selected for this writer.
    [[nodiscard]] LIBBSA_API ba2_gnrl_target target() const noexcept;

    /// Returns the immutable BA2 GNRL writer options selected at construction time.
    [[nodiscard]] LIBBSA_API const ba2_gnrl_writer_options &options() const noexcept;

    /// Adds a host-file payload with an explicit archive-internal path.
    LIBBSA_API result<void> add_file(std::string_view archive_path,
                                     std::string_view host_path,
                                     entry_compression_policy compression = entry_compression_policy::inherit);

    /// Adds a host-file payload with explicit BA2 GNRL per-entry options.
    LIBBSA_API result<void> add_file(std::string_view archive_path,
                                     std::string_view host_path,
                                     ba2_gnrl_entry_options options);

    /// Adds bytes copied from caller memory with an explicit archive-internal path.
    ///
    /// The writer owns an independent copy after this call, so callers may release
    /// or mutate the original memory before `write_to` is called.
    LIBBSA_API result<void> add_bytes(std::string_view archive_path,
                                      std::span<const std::byte> bytes,
                                      entry_compression_policy compression = entry_compression_policy::inherit);

    /// Adds copied memory bytes with explicit BA2 GNRL per-entry options.
    LIBBSA_API result<void> add_bytes(std::string_view archive_path,
                                      std::span<const std::byte> bytes,
                                      ba2_gnrl_entry_options options);

    /// Finalizes the writer state into a new BA2 GNRL archive at `host_path`.
    ///
    /// Existing destinations fail unless `ba2_gnrl_writer_options::overwrite_existing`
    /// was enabled. Publication uses a writer-owned temporary directory beside `host_path`,
    /// overwrites only supported regular-file destinations, rejects detectable reparse points,
    /// and returns validation, compression, or I/O failures as structured errors.
    LIBBSA_API result<void> write_to(std::string_view host_path) const;

    /// Finalizes the BA2 GNRL writer using explicit write-call execution controls.
    ///
    /// `execution.worker_count` must be positive. A value of `1` preserves the
    /// serial behavior and output-publication policy of the one-argument overload.
    LIBBSA_API result<void> write_to(std::string_view host_path, write_execution_options execution) const;

  private:
    struct state;

    std::unique_ptr<state> state_;
  };

  /// Public writer for creating new BA2 DX10/DDS texture archives.
  ///
  /// Entries are added from DDS host files with explicit archive-internal paths and
  /// finalized to a host-path archive. The public DX10 contract is compressed-only
  /// at archive level: callers do not choose raw, per-entry, or per-chunk overrides
  /// because uncompressed texture archives are not a stable compatibility target.
  /// DDS data is snapshotted when files are added, and `write_to` consumes the
  /// BA2 DX10 writer after any ordinary write attempt so that writer-owned snapshot
  /// data can be cleaned promptly instead of retained for retry.
  ///
  /// Thread-safety: separately constructed or moved-to writer objects may be used
  /// concurrently, but mutation is not concurrent with other mutation or
  /// `write_to` on the same writer object. See `docs/thread-safety.md`.
  class ba2_dx10_writer
  {
  public:
    /// Creates a writer for `target` using default BA2 DX10 writer options.
    LIBBSA_API explicit ba2_dx10_writer(ba2_dx10_target target);

    /// Creates a writer for `target` using the supplied texture archive options.
    LIBBSA_API explicit ba2_dx10_writer(ba2_dx10_target target, ba2_dx10_writer_options options);

    /// Destroys the writer and releases any staged texture snapshot state it owns.
    LIBBSA_API ~ba2_dx10_writer();

    /// Copying is disabled because writer copies would alias mutable staged texture snapshots.
    ba2_dx10_writer(const ba2_dx10_writer &) = delete;

    /// Copy assignment is disabled because writer copies would alias mutable staged texture snapshots.
    ba2_dx10_writer &operator=(const ba2_dx10_writer &) = delete;

    /// Transfers staged texture snapshots and options from `other`.
    ///
    /// After the move, `other` is valid only for destruction or reassignment.
    LIBBSA_API ba2_dx10_writer(ba2_dx10_writer &&other) noexcept;

    /// Replaces this writer by taking staged texture snapshots and options from `other`.
    ///
    /// Any snapshot state previously owned by this writer is cleaned up before ownership transfers.
    /// After the move, `other` is valid only for destruction or reassignment.
    LIBBSA_API ba2_dx10_writer &operator=(ba2_dx10_writer &&other) noexcept;

    /// Returns the BA2 DX10 target profile selected for this writer.
    [[nodiscard]] LIBBSA_API ba2_dx10_target target() const noexcept;

    /// Returns the immutable BA2 DX10 writer options selected at construction time.
    [[nodiscard]] LIBBSA_API const ba2_dx10_writer_options &options() const noexcept;

    /// Adds a DDS host-file payload with an explicit archive-internal texture path.
    ///
    /// The DDS file is validated and snapshotted at add time; expected caller-data
    /// failures are reported through `result<void>`. After `write_to` has consumed
    /// this BA2 DX10 writer, later `add_file` calls fail through `result<void>` with
    /// `error_code::invalid_argument` rather than reusing stale staged snapshots.
    LIBBSA_API result<void> add_file(std::string_view archive_path, std::string_view dds_host_path);

    /// Finalizes the writer state into a new BA2 DX10 archive at `host_path`.
    ///
    /// Existing destinations fail unless `ba2_dx10_writer_options::overwrite_existing`
    /// was enabled. Publication uses a writer-owned temporary directory beside `host_path`,
    /// overwrites only supported regular-file destinations, rejects detectable reparse points,
    /// and returns validation, compression, or I/O failures as structured errors.
    /// `write_to` is a consuming operation for BA2 DX10: after any ordinary attempt,
    /// whether it succeeds or returns a `result` error, successful completion and
    /// ordinary failure unwinding run best-effort snapshot cleanup. Later `write_to`
    /// calls fail through `result<void>` with `error_code::invalid_argument`.
    LIBBSA_API result<void> write_to(std::string_view host_path) const;

    /// Finalizes the BA2 DX10 writer using explicit write-call execution controls.
    ///
    /// `execution.worker_count` must be positive. A value of `1` preserves the
    /// serial behavior and output-publication policy of the one-argument overload.
    /// The BA2 DX10 consumed-after-write and best-effort snapshot cleanup rules are
    /// identical to the one-argument overload.
    LIBBSA_API result<void> write_to(std::string_view host_path, write_execution_options execution) const;

  private:
    struct state;

    std::unique_ptr<state> state_;
  };

} // namespace libbsa

