}
function walk(dir, out=[]) { for (const name of fs.readdirSync(dir)) { const p = path.join(dir, name); const st = fs.statSync(p); if (st.isDirectory()) walk(p, out); else out.push(p.replaceAll('\\\\','/').replaceAll('\\','/')); } return out; }
