  try {
    const data = JSON.parse(fs.readFileSync(p, 'utf8'));
    if (Array.isArray(data.rows)) {
      const fams = [...new Set(data.rows.map(r => r.family || '?'))].sort();
      console.log(`- ${p}: rows=${data.rows.length} families=${fams.join(',')} kind=${data.matrix_kind}`);
    } else if (Array.isArray(data.entries)) {
      console.log(`- ${p}: entries=${data.entries.length} variant=${data.variant} version=${data.version} provenance=${String(data.provenance).slice(0,60)}`);
    } else if (Array.isArray(data.cases)) {
      console.log(`- ${p}: cases=${data.cases.length} provenance=${String(data.provenance).slice(0,60)}`);
    } else {
      console.log(`- ${p}: keys=${Object.keys(data).slice(0,6).join(',')}`);
    }
  } catch (e) { console.log(`- ${p}: unreadable json ${e.message}`); }
}

